'use client';

import Image from 'next/image';
import { useEffect, useMemo, useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useGSAP } from '@gsap/react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import {
  AlertTriangle, ArrowRight, BarChart3, BedDouble, Bell, Building2, CalendarCheck,
  CalendarRange, CheckCircle2, CircleDollarSign, Compass, FileCheck2, Home,
  LogOut, Megaphone, Pencil, Plus, Search, Settings, ShieldCheck, Star, Trash2,
  UserRound, Users, WalletCards, X, type LucideIcon,
} from 'lucide-react';
import type { Listing } from '@/lib/domain';
import type { PlatformActionResponse, PlatformResponse } from '@/lib/contracts';
import { CEBU_LOCATIONS } from '@/constants/cebu-locations';
import { handleResponse, isAuthenticationError } from '@/services/api.service';
import { DashboardLoadState } from '@/components/common/DashboardLoadState';
import { useModalAccessibility } from '@/hooks/use-modal-accessibility';

gsap.registerPlugin(useGSAP, ScrollTrigger);

type Tab = 'overview' | 'listings' | 'bookings' | 'availability' | 'guests' | 'promotions' | 'reviews' | 'finance' | 'notifications' | 'profile';

const TAB_COPY: Record<Tab, { title: string; description: string }> = {
  overview: { title: 'Run the stay behind the journey.', description: 'See what travelers need next, keep inventory accurate, and move every confirmed stay forward.' },
  listings: { title: 'Your places and experiences.', description: 'Create inventory travelers can discover, then keep pricing, capacity, and location details current.' },
  bookings: { title: 'Traveler requests, clearly handled.', description: 'Review every reservation and respond to change or cancellation requests without losing context.' },
  availability: { title: 'Control every available date.', description: 'Block dates that cannot be sold and keep traveler requests aligned with real operating capacity.' },
  guests: { title: 'Guests connected by real bookings.', description: 'See only travelers who requested or completed a stay with your inventory.' },
  promotions: { title: 'Price the season deliberately.', description: 'Schedule listing discounts without replacing your standard nightly rate.' },
  reviews: { title: 'Traveler feedback in context.', description: 'Read verified reviews tied to completed bookings and specific listings.' },
  finance: { title: 'A transparent payment picture.', description: 'Track simulated held, released, and frozen balances while the real payment integration remains disabled.' },
  notifications: { title: 'Every operational update, in one place.', description: 'Keep booking, cancellation, review, and account events visible and acknowledged.' },
  profile: { title: 'Build traveler confidence.', description: 'Keep business contact details current and understand how profile verification affects visibility.' },
};

async function request(): Promise<PlatformResponse>;
async function request(body: Record<string, unknown>): Promise<PlatformActionResponse>;
async function request(body?: Record<string, unknown>): Promise<PlatformResponse | PlatformActionResponse> {
  const response = await fetch(body ? '/api/platform' : '/api/platform?scope=owner', body ? { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) } : undefined);
  return body ? handleResponse<PlatformActionResponse>(response) : handleResponse<PlatformResponse>(response);
}

const money = (value: number) => `PHP ${value.toLocaleString()}`;
const titleCase = (value: string) => value.replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());

export default function OwnerDashboard() {
  const router = useRouter();
  const pageRef = useRef<HTMLDivElement | null>(null);
  const [data, setData] = useState<PlatformResponse | null>(null);
  const [tab, setTab] = useState<Tab>('overview');
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState('all');
  const [editing, setEditing] = useState<Listing | 'new' | null>(null);
  const [loadError, setLoadError] = useState('');

  const refresh = () => request().then(setData);
  const loadInitial = async () => {
    try { setData(await request()); }
    catch (error) {
      if (isAuthenticationError(error)) { router.replace('/'); return; }
      setLoadError(error instanceof Error ? error.message : 'TravelMate could not load the owner workspace.');
    }
  };

  useEffect(() => {
    void request().then(setData).catch((error: unknown) => {
      if (isAuthenticationError(error)) { router.replace('/'); return; }
      setLoadError(error instanceof Error ? error.message : 'TravelMate could not load the owner workspace.');
    });
  }, [router]);

  useGSAP(() => {
    if (!data || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const media = gsap.matchMedia();
    gsap.from('[data-owner-reveal]', { y: 24, opacity: 0, duration: 0.7, stagger: 0.07, ease: 'power3.out' });
    gsap.from('[data-owner-card]', { y: 38, opacity: 0, duration: 0.75, stagger: 0.08, ease: 'power3.out' });
    gsap.fromTo('[data-owner-hero-image]', { scale: 0.88, opacity: 0.62 }, { scale: 1, opacity: 1, ease: 'none', scrollTrigger: { trigger: '[data-owner-hero]', start: 'top 84%', end: 'bottom 34%', scrub: 0.45 } });
    media.add('(min-width: 1024px)', () => {
      const rail = document.querySelector<HTMLElement>('[data-owner-rail]');
      const shell = document.querySelector<HTMLElement>('[data-owner-shell]');
      if (!rail || !shell) return;
      ScrollTrigger.create({ trigger: shell, start: 'top top+=80', end: 'bottom bottom-=32', pin: rail, pinSpacing: false });
    });
    ScrollTrigger.refresh();
    return () => media.revert();
  }, { scope: pageRef, dependencies: [data, tab], revertOnUpdate: true });

  async function act(body: Record<string, unknown>, success: string) {
    setBusy(true); setMessage('');
    try { await request(body); await refresh(); setMessage(success); }
    catch (error) { setMessage(error instanceof Error ? error.message : 'Action failed.'); }
    finally { setBusy(false); }
  }

  async function logout() {
    await fetch('/api/auth', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'logout' }) });
    router.replace('/');
  }

  const filtered = useMemo(() => data?.listings.filter((item) => (status === 'all' || item.status === status) && `${item.name} ${item.municipality}`.toLowerCase().includes(search.toLowerCase())) ?? [], [data, search, status]);
  if (!data) return <DashboardLoadState label="the owner workspace" error={loadError} onRetry={() => { setLoadError(''); void loadInitial(); }} />;

  const requests = data.bookings.filter((item) => item.status === 'pending' || item.status === 'cancel_requested' || item.status === 'change_requested');
  const unreadNotifications = data.notifications.filter((item) => !item.readAt);
  const pendingListings = data.listings.filter((item) => item.status === 'pending');
  const approvedListings = data.listings.filter((item) => item.status === 'approved');
  const occupancy = data.listings.reduce((sum, item) => sum + item.capacity - item.available, 0);
  const capacity = data.listings.reduce((sum, item) => sum + item.capacity, 0);
  const occupancyRate = capacity ? Math.round((occupancy / capacity) * 100) : 0;
  const listingName = (id: string) => data.listings.find((item) => item.id === id)?.name || id;
  const travelerName = (id: string) => data.directory.find((item) => item.id === id)?.name || 'Traveler';
  const initials = data.user.name.split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase();
  const currentCopy = TAB_COPY[tab];
  const navItems: Array<[Tab, string, LucideIcon]> = [['overview', 'Home', Home], ['listings', 'Listings', Building2], ['bookings', 'Bookings', CalendarCheck], ['availability', 'Availability', CalendarRange], ['guests', 'Guests', Users], ['promotions', 'Promotions', Megaphone], ['reviews', 'Reviews', Star], ['finance', 'Finance', WalletCards]];

  return <div ref={pageRef} className="min-h-screen w-full max-w-full overflow-x-hidden bg-[#0b1d1a] text-slate-100">
    <a href="#owner-main-content" className="sr-only z-[100] bg-[#f1ead8] px-4 py-2 font-bold text-[#14231f] focus:not-sr-only focus:fixed focus:left-4 focus:top-4">Skip to owner workspace</a>
    <header className="sticky top-0 z-40 border-b border-white/10 bg-[#0b1d1a]/94 px-4 backdrop-blur-xl sm:px-6"><div className="mx-auto flex h-20 w-full max-w-[1600px] items-center justify-between">
      <button className="group flex items-center gap-3 text-left" onClick={() => router.push('/')}><span className="grid h-10 w-10 place-items-center border border-amber-300/40 bg-amber-300 text-[#12231f] transition-transform duration-500 group-hover:-rotate-6"><Compass size={21}/></span><span><strong className="block text-lg font-black tracking-[-0.03em]">TravelMate</strong><span className="hidden text-[10px] tracking-[0.18em] text-white/45 sm:block">HOST WITH CONTEXT</span></span></button>
      <div className="flex items-center gap-2 sm:gap-4"><span className="hidden text-sm text-white/55 sm:block">{data.user.name}</span><button type="button" aria-label="Open notifications" title="Open notifications" onClick={() => setTab('notifications')} className="relative grid h-10 w-10 place-items-center border border-white/10 text-white/65 transition hover:border-cyan-300/50 hover:bg-cyan-300 hover:text-[#12231f]"><Bell size={17}/>{unreadNotifications.length > 0 && <span className="absolute -right-1 -top-1 grid h-5 min-w-5 place-items-center bg-amber-300 px-1 text-[10px] font-black text-[#14231f]">{unreadNotifications.length}</span>}</button><button type="button" aria-label="Sign out" title="Sign out" onClick={logout} className="grid h-10 w-10 place-items-center border border-white/10 text-white/65 transition hover:border-amber-300/50 hover:bg-amber-300 hover:text-[#12231f]"><LogOut size={17}/></button></div>
    </div></header>

    <div data-owner-shell className="mx-auto grid w-full max-w-[1600px] grid-cols-[minmax(0,1fr)] gap-0 px-4 lg:grid-cols-[248px_minmax(0,1fr)] lg:gap-10 lg:px-6 xl:gap-14">
      <aside className="min-w-0 max-w-[calc(100vw-2rem)] py-4 lg:max-w-none lg:py-8"><div data-owner-rail className="lg:flex lg:h-[calc(100vh-144px)] lg:w-[248px] lg:flex-col lg:overflow-y-auto">
        <nav aria-label="Owner workspace" className="flex max-w-full snap-x gap-px overflow-x-auto border border-white/10 bg-white/10 p-px lg:flex-col lg:overflow-visible">{navItems.map(([id, label, Icon]) => <button key={id} aria-current={tab === id ? 'page' : undefined} onClick={() => setTab(id)} className={`group relative flex shrink-0 snap-start items-center gap-3 px-4 py-3.5 text-sm font-semibold transition-colors lg:w-full ${tab === id ? 'bg-[#f1ead8] text-[#14231f]' : 'bg-[#0b1d1a] text-white/55 hover:bg-[#16302b] hover:text-white'}`}><span className={`absolute inset-y-0 left-0 w-0.5 ${tab === id ? 'bg-amber-400' : 'bg-transparent'}`}/><Icon size={17}/>{label}{id === 'bookings' && requests.length > 0 && <span className="ml-auto bg-amber-300 px-1.5 py-0.5 text-[10px] font-black text-[#14231f]">{requests.length}</span>}</button>)}<button aria-current={tab === 'profile' ? 'page' : undefined} onClick={() => setTab('profile')} className={`group relative flex shrink-0 snap-start items-center gap-3 px-4 py-3.5 text-sm font-semibold transition-colors lg:hidden ${tab === 'profile' ? 'bg-[#f1ead8] text-[#14231f]' : 'bg-[#0b1d1a] text-white/55 hover:bg-[#16302b] hover:text-white'}`}><span className={`absolute inset-y-0 left-0 w-0.5 ${tab === 'profile' ? 'bg-amber-400' : 'bg-transparent'}`}/><ShieldCheck size={17}/>Account</button></nav>
        <div className="mt-8 hidden border-t border-white/10 pt-5 lg:block"><p className="max-w-[24ch] text-xs leading-5 text-white/38">Travelers discover approved inventory. Keep availability honest and respond to booking requests promptly.</p></div>
        <button onClick={() => setTab('profile')} className={`mt-auto hidden w-full items-center gap-3 border p-3 text-left transition lg:flex ${tab === 'profile' ? 'border-amber-300/50 bg-amber-300/10' : 'border-white/10 bg-white/[0.035] hover:border-white/25 hover:bg-white/[0.06]'}`} aria-label="Open owner profile"><span className="grid h-10 w-10 shrink-0 place-items-center bg-amber-300 text-sm font-black text-[#14231f]">{initials}</span><span className="min-w-0 flex-1"><strong className="block truncate text-sm text-white">{data.user.name}</strong><span className="block truncate text-[11px] text-white/38">{data.user.email}</span></span><UserRound size={16} className="shrink-0 text-amber-300"/></button>
      </div></aside>

      <main id="owner-main-content" tabIndex={-1} className="min-w-0 w-full max-w-[calc(100vw-2rem)] overflow-x-hidden pb-20 pt-5 outline-none lg:max-w-none lg:pt-10">
        <div data-owner-reveal className="mb-7 flex flex-col items-start gap-3 border-b border-white/10 pb-6 sm:flex-row sm:flex-wrap sm:items-end sm:justify-between"><div className="min-w-0 max-w-5xl"><h1 className="break-words text-[clamp(2rem,4vw,3.75rem)] font-black leading-[0.96] tracking-[-0.05em]">{currentCopy.title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-white/52">{currentCopy.description}</p></div><span className={`w-fit shrink-0 border px-3 py-2 text-[11px] font-bold tracking-wide ${data.user.profileStatus === 'verified' ? 'border-emerald-400/40 bg-emerald-400/10 text-emerald-200' : 'border-amber-300/40 bg-amber-300/10 text-amber-200'}`}>{data.user.profileStatus === 'verified' ? `Verified · Trust ${data.user.trustScore}` : `Limited Mode · Trust ${data.user.trustScore}`}</span></div>
        {message && <div role="status" aria-live="polite" className="mb-6 border-l-2 border-amber-300 bg-white/[0.055] px-4 py-3 text-sm text-white/80">{message}</div>}

        {tab === 'overview' && <div className="space-y-5">
          <section data-owner-hero data-owner-card className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 xl:grid-cols-12"><article className="relative flex min-h-[360px] flex-col justify-end overflow-hidden bg-[#efe8d6] p-6 text-[#14231f] sm:p-10 xl:col-span-8"><div className="relative z-10 max-w-4xl"><p className="text-sm font-semibold text-[#4a655e]">Built for the traveler’s next step</p><h2 className="mt-3 max-w-5xl text-[clamp(2.6rem,5vw,5.3rem)] font-black leading-[0.9] tracking-[-0.06em]">Turn local inventory into a trip they can trust.</h2><p className="mt-6 max-w-2xl text-sm leading-6 text-[#49635c]">TravelMate connects your approved stays and experiences to traveler planning. Accurate capacity, quick request decisions, and a verified profile make that connection useful.</p></div></article><article className="group relative min-h-[360px] overflow-hidden bg-[#14231f] xl:col-span-4"><Image data-owner-hero-image src="/beach-bg.png" alt="Tropical destination near TravelMate owner listings" fill priority sizes="(max-width: 1280px) 100vw, 420px" className="object-cover opacity-85 contrast-125 transition-transform duration-700 ease-out group-hover:scale-105"/><div className="absolute inset-0 bg-gradient-to-t from-[#071a16] via-[#071a16]/25 to-transparent"/><div className="absolute inset-x-0 bottom-0 z-10 p-6 sm:p-8"><p className="max-w-xs text-sm leading-6 text-white/76">{approvedListings.length ? `${approvedListings.length} approved ${approvedListings.length === 1 ? 'listing is' : 'listings are'} ready for traveler discovery.` : 'Create your first listing and submit it for approval.'}</p><button onClick={() => setEditing('new')} className="mt-5 inline-flex min-h-12 items-center gap-3 bg-amber-300 px-5 py-3 text-sm font-black text-[#14231f] transition hover:bg-amber-200">Add a listing <ArrowRight size={16}/></button></div></article></section>
          <section data-owner-card aria-label="Owner metrics" className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 sm:grid-cols-2 xl:grid-cols-12"><Metric icon={Building2} label="Active listings" value={String(approvedListings.length)} helper={`${pendingListings.length} awaiting review`} className="xl:col-span-3"/><Metric icon={CalendarCheck} label="Booking requests" value={String(data.metrics.bookingRequests)} helper={`${requests.length} request${requests.length === 1 ? '' : 's'} need a decision`} className="xl:col-span-3"/><Metric icon={BarChart3} label="Listing views" value={String(data.metrics.listingViews)} helper={`${data.metrics.listingViews ? Math.round((data.metrics.bookingRequests / data.metrics.listingViews) * 100) : 0}% request conversion`} className="xl:col-span-3"/><Metric icon={CircleDollarSign} label="Released revenue" value={money(data.metrics.revenue)} helper={`${occupancyRate}% current occupancy`} className="xl:col-span-3"/></section>
          <section data-owner-card className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 xl:grid-cols-12"><article className="bg-[#102622] p-5 sm:p-7 xl:col-span-7"><PanelHeading icon={Bell} title="Needs your attention" description="Resolve the items that can block a traveler or delay publication."/><div className="divide-y divide-white/10">{requests.length === 0 && pendingListings.length === 0 && <EmptyState icon={CheckCircle2} title="Everything is moving" text="No booking requests or pending listing reviews need attention."/>}{requests.map((item) => <button key={item.id} onClick={() => setTab('bookings')} className="group flex w-full items-center justify-between gap-4 py-4 text-left transition hover:pl-2"><span><strong className="block text-sm">{travelerName(item.travelerId)} requested {item.status === 'pending' ? 'a new booking' : item.status === 'cancel_requested' ? 'a cancellation' : 'a booking change'}</strong><span className="mt-1 block text-xs text-white/38">{listingName(item.listingId)}</span></span><ArrowRight size={17} className="shrink-0 text-amber-300 transition-transform group-hover:translate-x-1"/></button>)}{pendingListings.map((item) => <button key={item.id} onClick={() => setTab('listings')} className="group flex w-full items-center justify-between gap-4 py-4 text-left transition hover:pl-2"><span><strong className="block text-sm">{item.name} is awaiting review</strong><span className="mt-1 block text-xs text-white/38">Travelers will see it after administrator approval.</span></span><ArrowRight size={17} className="shrink-0 text-amber-300 transition-transform group-hover:translate-x-1"/></button>)}</div></article><article className="bg-[#14231f] p-5 sm:p-7 xl:col-span-5"><PanelHeading icon={BarChart3} title="Inventory health" description="Occupied guest slots across your most recent inventory."/>{data.listings.length === 0 ? <EmptyState icon={BedDouble} title="No inventory yet" text="Add a stay, activity, food experience, or transport service to begin."/> : <div className="space-y-5">{data.listings.slice(0, 5).map((item) => { const used = item.capacity - item.available; const rate = item.capacity ? Math.round((used / item.capacity) * 100) : 0; return <div key={item.id}><div className="mb-2 flex items-end justify-between gap-3"><span><strong className="block text-sm">{item.name}</strong><span className="text-[11px] text-white/36">{item.municipality}</span></span><span className="text-xs font-bold text-cyan-200">{used}/{item.capacity}</span></div><div className="h-2 overflow-hidden bg-black/25"><div className="h-full bg-cyan-300 transition-[width] duration-700" style={{ width: `${rate}%` }}/></div></div>})}</div>}</article></section>
          <section data-owner-card className="flex flex-col justify-between gap-6 bg-amber-300 p-6 text-[#14231f] sm:flex-row sm:items-end sm:p-9"><div><p className="text-sm font-semibold text-[#5e5a33]">Visibility begins with confidence</p><h2 className="mt-2 max-w-3xl text-3xl font-black tracking-[-0.045em] sm:text-5xl">Complete the details travelers need before they choose.</h2></div><button onClick={() => setTab(data.user.profileStatus === 'verified' ? 'listings' : 'profile')} className="inline-flex min-h-12 shrink-0 items-center justify-center gap-3 bg-[#14231f] px-5 py-3 text-sm font-black text-white transition hover:bg-[#203b34]">{data.user.profileStatus === 'verified' ? 'Review listings' : 'Complete profile'} <ArrowRight size={16}/></button></section>
        </div>}
        {tab === 'listings' && <ListingsView listings={filtered} total={data.listings.length} search={search} status={status} busy={busy} onSearch={setSearch} onStatus={setStatus} onNew={() => setEditing('new')} onEdit={setEditing} onDelete={(item) => { if (confirm(`Delete ${item.name}?`)) void act({ action: 'delete-listing', id: item.id }, 'Listing deleted.'); }}/>} 
        {tab === 'bookings' && <BookingsView data={data} busy={busy} listingName={listingName} travelerName={travelerName} onDecision={(id, decision) => void act({ action: 'owner-request-decision', id, decision }, `Traveler request ${decision === 'approve' ? 'approved' : 'declined'}.`)}/>} 
        {tab === 'availability' && <AvailabilityView data={data} busy={busy} onAction={(body, success) => void act(body, success)}/>} 
        {tab === 'guests' && <GuestsView data={data} listingName={listingName}/>} 
        {tab === 'promotions' && <PromotionsView data={data} busy={busy} onAction={(body, success) => void act(body, success)}/>} 
        {tab === 'reviews' && <ReviewsView data={data} listingName={listingName} travelerName={travelerName}/>} 
        {tab === 'finance' && <div className="space-y-5"><FinanceView data={data} busy={busy} listingName={listingName} travelerName={travelerName} onRelease={(id) => void act({ action: 'release-payment', id }, 'Simulated payment marked as released.')}/><TransactionHistory data={data}/></div>} 
        {tab === 'notifications' && <NotificationsView data={data} busy={busy} onAction={(body, success) => void act(body, success)}/>} 
        {tab === 'profile' && <ProfileView data={data} busy={busy} onSubmit={(phone, bio) => void act({ action: 'submit-profile', phone, bio }, 'Profile sent for verification.')} onDocument={(body) => void act(body, 'Verification document submitted.')}/>} 
      </main>
    </div>
    {editing && <ListingDialog key={editing === 'new' ? 'new' : editing.id} listing={editing === 'new' ? undefined : editing} busy={busy} onClose={() => setEditing(null)} onSave={async (body) => { await act(body, editing === 'new' ? 'Listing submitted for approval.' : 'Listing updated.'); setEditing(null); }}/>} 
  </div>;
}

function Metric({ icon: Icon, label, value, helper, className = '' }: { icon: LucideIcon; label: string; value: string; helper: string; className?: string }) { return <article className={`group min-w-0 overflow-hidden bg-[#102622] p-5 transition-colors hover:bg-[#16302b] sm:p-6 ${className}`}><div className="flex items-start justify-between gap-4"><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/36">{label}</p><Icon size={17} className="text-cyan-200 transition-transform duration-500 group-hover:scale-110"/></div><strong className="mt-6 block break-words text-3xl font-black tracking-[-0.045em]">{value}</strong><p className="mt-2 text-xs leading-5 text-white/38">{helper}</p></article>; }
function PanelHeading({ icon: Icon, title, description }: { icon: LucideIcon; title: string; description: string }) { return <div className="mb-5 flex items-start gap-4 border-b border-white/10 pb-5"><span className="grid h-11 w-11 shrink-0 place-items-center border border-cyan-300/30 text-cyan-200"><Icon size={19}/></span><div><h2 className="text-xl font-black tracking-[-0.03em]">{title}</h2><p className="mt-1 max-w-md text-xs leading-5 text-white/42">{description}</p></div></div>; }
function EmptyState({ icon: Icon, title, text }: { icon: LucideIcon; title: string; text: string }) { return <div className="flex min-h-44 flex-col items-start justify-center py-7"><Icon size={25} className="text-amber-300"/><strong className="mt-4 text-base">{title}</strong><p className="mt-2 max-w-sm text-sm leading-6 text-white/42">{text}</p></div>; }

function ListingsView({ listings, total, search, status, busy, onSearch, onStatus, onNew, onEdit, onDelete }: { listings: Listing[]; total: number; search: string; status: string; busy: boolean; onSearch: (value: string) => void; onStatus: (value: string) => void; onNew: () => void; onEdit: (listing: Listing) => void; onDelete: (listing: Listing) => void }) {
  return <div data-owner-card className="space-y-5"><section className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 xl:grid-cols-12"><div className="bg-[#102622] p-5 sm:p-7 xl:col-span-8"><PanelHeading icon={Search} title="Find and filter inventory" description="Search by listing or municipality, then narrow the operational state."/><div className="grid gap-3 sm:grid-cols-[1fr_190px]"><label className="relative"><span className="sr-only">Search listings</span><Search size={16} className="absolute left-4 top-4 text-white/35"/><input value={search} onChange={(event) => onSearch(event.target.value)} placeholder="Search listing or municipality" className="min-h-12 w-full border border-white/15 bg-[#071a16] pl-11 pr-4 text-sm text-white placeholder:text-white/28 focus:border-cyan-300 focus:outline-none"/></label><select aria-label="Filter listings by status" value={status} onChange={(event) => onStatus(event.target.value)} className="min-h-12 border border-white/15 bg-[#071a16] px-4 text-sm text-white focus:border-cyan-300 focus:outline-none"><option value="all">All statuses</option><option value="approved">Approved</option><option value="pending">Pending</option><option value="rejected">Rejected</option></select></div></div><div className="flex flex-col justify-between bg-amber-300 p-6 text-[#14231f] xl:col-span-4"><div><Building2 size={24}/><strong className="mt-6 block text-4xl font-black">{total}</strong><p className="mt-2 text-sm text-[#4f5c55]">Total owner listings</p></div><button disabled={busy} onClick={onNew} className="mt-8 inline-flex min-h-12 items-center justify-center gap-2 bg-[#14231f] px-5 py-3 text-sm font-black text-white disabled:opacity-50"><Plus size={17}/>New listing</button></div></section>{listings.length === 0 ? <section className="border border-white/10 bg-[#102622] p-8"><EmptyState icon={Building2} title="No listings match" text="Adjust the search or status filter, or create new inventory for travelers."/></section> : <div className="overflow-x-auto border border-white/10"><table className="w-full min-w-[820px] text-sm"><thead className="bg-[#14231f] text-[10px] uppercase tracking-[0.12em] text-white/38"><tr><th className="p-4 text-left">Listing</th><th className="text-left">Status</th><th className="text-left">Price</th><th className="text-left">Availability</th><th className="text-left">Location</th><th className="p-4 text-right">Actions</th></tr></thead><tbody className="bg-[#102622]">{listings.map((item) => <tr key={item.id} className="border-t border-white/10 transition hover:bg-white/[0.035]"><td className="p-4"><strong>{item.name}</strong><p className="mt-1 text-xs capitalize text-white/38">{item.category}</p></td><td><Status value={item.status}/></td><td className="font-semibold">{money(item.price)}</td><td><strong>{item.available}</strong><span className="text-white/38">/{item.capacity} open</span></td><td className="max-w-52 text-white/55"><strong className="text-white/80">{item.municipality}</strong><p className="mt-1 truncate text-xs">{item.address || 'Address not set'}</p></td><td className="p-4"><div className="flex justify-end gap-1"><button type="button" aria-label={`Edit ${item.name}`} title="Edit listing" onClick={() => onEdit(item)} className="grid h-10 w-10 place-items-center border border-white/10 transition hover:border-cyan-300 hover:bg-cyan-300 hover:text-[#14231f]"><Pencil size={15}/></button><button type="button" aria-label={`Delete ${item.name}`} title="Delete listing" onClick={() => onDelete(item)} className="grid h-10 w-10 place-items-center border border-white/10 text-red-300 transition hover:border-red-300 hover:bg-red-300 hover:text-[#33130f]"><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>}</div>;
}

function BookingsView({ data, busy, listingName, travelerName, onDecision }: { data: PlatformResponse; busy: boolean; listingName: (id: string) => string; travelerName: (id: string) => string; onDecision: (id: string, decision: 'approve' | 'decline') => void }) {
  const requests = data.bookings.filter((item) => ['pending', 'cancel_requested', 'change_requested'].includes(item.status));
  return <div data-owner-card className="space-y-5"><section className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 sm:grid-cols-2 xl:grid-cols-12"><Metric icon={CalendarCheck} label="All bookings" value={String(data.bookings.length)} helper="Across approved owner inventory" className="xl:col-span-4"/><Metric icon={Bell} label="Needs decision" value={String(requests.length)} helper="New, change, and cancellation requests" className="xl:col-span-4"/><Metric icon={Users} label="Booked guests" value={String(data.bookings.filter((item) => item.status === 'confirmed' || item.status === 'completed').reduce((sum, item) => sum + item.guests, 0))} helper="Confirmed guest count" className="xl:col-span-4"/></section>{data.bookings.length === 0 ? <section className="border border-white/10 bg-[#102622] p-8"><EmptyState icon={CalendarCheck} title="No bookings yet" text="Approved inventory will appear in traveler search and new requests will show here."/></section> : <div className="overflow-x-auto border border-white/10"><table className="w-full min-w-[980px] text-sm"><thead className="bg-[#14231f] text-[10px] uppercase tracking-[0.12em] text-white/38"><tr><th className="p-4 text-left">Traveler</th><th className="text-left">Listing</th><th className="text-left">Stay dates</th><th className="text-left">Booking</th><th className="text-left">Payment</th><th className="p-4 text-right">Decision</th></tr></thead><tbody className="bg-[#102622]">{data.bookings.map((item) => <tr key={item.id} className="border-t border-white/10 align-top"><td className="p-4"><strong>{travelerName(item.travelerId)}</strong><p className="mt-1 text-xs text-white/38">{new Date(item.createdAt).toLocaleDateString()}</p></td><td className="py-4">{listingName(item.listingId)}{item.requestNote && <p className="mt-2 max-w-52 text-xs leading-5 text-amber-200">{item.requestNote}</p>}</td><td className="py-4">{item.checkIn || 'Date pending'} → {item.checkOut || 'Date pending'}<p className="mt-1 text-xs text-white/38">{item.guests} guest{item.guests === 1 ? '' : 's'} · {item.nights} night{item.nights === 1 ? '' : 's'}</p>{item.requestedCheckIn && <p className="mt-2 text-xs text-cyan-200">Requested: {item.requestedCheckIn} → {item.requestedCheckOut} · {item.requestedGuests} guests</p>}</td><td className="py-4"><Status value={item.status}/></td><td className="py-4"><span className="text-xs font-bold">{titleCase(item.paymentStatus)}</span><p className="mt-1 font-mono text-xs text-white/45">{money(item.amount)}</p></td><td className="p-4"><div className="flex justify-end gap-2">{['pending', 'cancel_requested', 'change_requested'].includes(item.status) ? <><button disabled={busy} onClick={() => onDecision(item.id, 'approve')} className="min-h-10 bg-amber-300 px-3 text-xs font-black text-[#14231f] disabled:opacity-50">Approve</button><button disabled={busy} onClick={() => onDecision(item.id, 'decline')} className="min-h-10 border border-white/20 px-3 text-xs font-bold disabled:opacity-50">Decline</button></> : <span className="text-xs text-white/32">No action needed</span>}</div></td></tr>)}</tbody></table></div>}</div>;
}

type OwnerAction = (body: Record<string, unknown>, success: string) => void;

function AvailabilityView({ data, busy, onAction }: { data: PlatformResponse; busy: boolean; onAction: OwnerAction }) {
  return <div data-owner-card className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 xl:grid-cols-12"><form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onAction({ action: 'block-date', listingId: form.get('listingId'), date: form.get('date'), reason: form.get('reason') }, 'Date blocked for new booking requests.'); event.currentTarget.reset(); }} className="bg-[#efe8d6] p-6 text-[#14231f] sm:p-8 xl:col-span-5"><CalendarRange size={28}/><h2 className="mt-7 text-4xl font-black tracking-[-0.05em]">Block an unavailable date.</h2><p className="mt-4 text-sm leading-6 text-[#52635e]">Blocked nights cannot be included in a new traveler request.</p><div className="mt-8 space-y-4"><label className="block text-xs font-bold">Listing<select required name="listingId" className="mt-2 min-h-12 w-full border border-[#14231f]/25 bg-white px-4"><option value="">Choose listing</option>{data.listings.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="block text-xs font-bold">Date<input required name="date" type="date" className="mt-2 min-h-12 w-full border border-[#14231f]/25 bg-white px-4"/></label><label className="block text-xs font-bold">Reason<input name="reason" placeholder="Maintenance, private event…" className="mt-2 min-h-12 w-full border border-[#14231f]/25 bg-white px-4"/></label><button disabled={busy || data.listings.length === 0} className="min-h-12 w-full bg-[#14231f] px-5 font-black text-white disabled:opacity-50">Block date</button></div></form><section className="bg-[#102622] p-6 sm:p-8 xl:col-span-7"><PanelHeading icon={CalendarRange} title="Blocked calendar" description="Remove a block as soon as the date becomes sellable again."/>{data.blockedDates.length === 0 ? <EmptyState icon={CheckCircle2} title="No blocked dates" text="All dates remain eligible for traveler requests, subject to capacity."/> : <div className="divide-y divide-white/10">{data.blockedDates.map((block) => <article key={block.id} className="flex flex-wrap items-center justify-between gap-4 py-4"><div><strong>{data.listings.find((item) => item.id === block.listingId)?.name || 'Listing'}</strong><p className="mt-1 text-xs text-white/45">{new Date(`${block.date}T00:00:00`).toLocaleDateString(undefined, { dateStyle: 'long' })} · {block.reason}</p></div><button disabled={busy} onClick={() => onAction({ action: 'unblock-date', listingId: block.listingId, date: block.date }, 'Date reopened.')} className="min-h-10 border border-white/20 px-4 text-xs font-bold hover:bg-white/10 disabled:opacity-50">Reopen</button></article>)}</div>}</section></div>;
}

function GuestsView({ data, listingName }: { data: PlatformResponse; listingName: (id: string) => string }) {
  const guests = data.directory.map((traveler) => { const bookings = data.bookings.filter((item) => item.travelerId === traveler.id); return { traveler, bookings, spend: bookings.reduce((sum, item) => sum + item.amount, 0) }; });
  return <div data-owner-card className="space-y-5"><section className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 sm:grid-cols-3"><Metric icon={Users} label="Connected guests" value={String(guests.length)} helper="Travelers linked by your bookings"/><Metric icon={CalendarCheck} label="Guest bookings" value={String(data.bookings.length)} helper="Requests and completed stays"/><Metric icon={CircleDollarSign} label="Booking value" value={money(data.bookings.reduce((sum, item) => sum + item.amount, 0))} helper="Simulated gross request value"/></section>{guests.length === 0 ? <section className="border border-white/10 bg-[#102622] p-8"><EmptyState icon={Users} title="No connected guests yet" text="A traveler appears here only after requesting one of your approved listings."/></section> : <div className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 md:grid-cols-2">{guests.map(({ traveler, bookings, spend }) => <article key={traveler.id} className="bg-[#102622] p-6"><div className="flex items-start justify-between gap-4"><div><h2 className="text-xl font-black">{traveler.name}</h2><p className="mt-1 text-xs text-white/42">{traveler.email}</p></div><span className="grid h-10 w-10 place-items-center bg-amber-300 font-black text-[#14231f]">{traveler.name[0]}</span></div><div className="mt-6 grid grid-cols-2 gap-px bg-white/10"><div className="bg-[#14231f] p-3"><small className="text-white/38">Bookings</small><strong className="mt-1 block">{bookings.length}</strong></div><div className="bg-[#14231f] p-3"><small className="text-white/38">Value</small><strong className="mt-1 block">{money(spend)}</strong></div></div><p className="mt-4 text-xs leading-5 text-white/45">{[...new Set(bookings.map((item) => listingName(item.listingId)))].join(' · ')}</p></article>)}</div>}</div>;
}

function PromotionsView({ data, busy, onAction }: { data: PlatformResponse; busy: boolean; onAction: OwnerAction }) {
  return <div data-owner-card className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 xl:grid-cols-12"><form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onAction({ action: 'create-promotion', listingId: form.get('listingId'), name: form.get('name'), discountPct: Number(form.get('discountPct')), startDate: form.get('startDate'), endDate: form.get('endDate') }, 'Promotion scheduled.'); event.currentTarget.reset(); }} className="bg-[#102622] p-6 sm:p-8 xl:col-span-5"><PanelHeading icon={Megaphone} title="Schedule a promotion" description="The active discount is applied when a traveler sends a request."/><div className="space-y-4"><Field label="Listing"><select required name="listingId"><option value="">Choose listing</option>{data.listings.filter((item) => item.status === 'approved').map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Offer name"><input required name="name" placeholder="Rainy season rate"/></Field><Field label="Discount percentage"><input required name="discountPct" type="number" min="1" max="90"/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Starts"><input required name="startDate" type="date"/></Field><Field label="Ends"><input required name="endDate" type="date"/></Field></div><button disabled={busy} className="min-h-12 w-full bg-amber-300 px-5 font-black text-[#14231f] disabled:opacity-50">Publish promotion</button></div></form><section className="bg-[#efe8d6] p-6 text-[#14231f] sm:p-8 xl:col-span-7"><h2 className="text-4xl font-black tracking-[-0.05em]">Seasonal pricing</h2><p className="mt-3 text-sm text-[#52635e]">Standard rates remain intact; promotions apply only inside their date window.</p>{data.promotions.length === 0 ? <div className="mt-10"><Megaphone size={25}/><strong className="mt-4 block">No promotions scheduled</strong></div> : <div className="mt-8 divide-y divide-[#14231f]/15 border-y border-[#14231f]/15">{data.promotions.map((promotion) => <article key={promotion.id} className="flex flex-wrap items-center justify-between gap-4 py-5"><div><strong>{promotion.name} · {promotion.discountPct}% off</strong><p className="mt-1 text-xs text-[#52635e]">{data.listings.find((item) => item.id === promotion.listingId)?.name} · {promotion.startDate} to {promotion.endDate}</p></div><button disabled={busy} onClick={() => onAction({ action: 'delete-promotion', id: promotion.id }, 'Promotion removed.')} className="min-h-10 border border-[#14231f]/30 px-4 text-xs font-black hover:bg-[#14231f] hover:text-white">Remove</button></article>)}</div>}</section></div>;
}

function ReviewsView({ data, listingName, travelerName }: { data: PlatformResponse; listingName: (id: string) => string; travelerName: (id: string) => string }) {
  const average = data.reviews.length ? data.reviews.reduce((sum, item) => sum + item.rating, 0) / data.reviews.length : 0;
  return <div data-owner-card className="space-y-5"><section className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 sm:grid-cols-2"><Metric icon={Star} label="Average rating" value={average ? `${average.toFixed(1)}/5` : '—'} helper="Verified completed-booking reviews"/><Metric icon={Users} label="Review count" value={String(data.reviews.length)} helper="Traveler feedback received"/></section>{data.reviews.length === 0 ? <section className="border border-white/10 bg-[#102622] p-8"><EmptyState icon={Star} title="No reviews yet" text="Travelers can review an owner listing after the stay is marked complete."/></section> : <div className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 lg:grid-cols-2">{data.reviews.map((review) => <article key={review.id} className="bg-[#102622] p-6"><div className="flex justify-between gap-4"><span className="font-black text-amber-300" aria-label={`${review.rating} out of 5 stars`}>{review.rating}/5 rating</span><time className="text-xs text-white/35">{new Date(review.createdAt).toLocaleDateString()}</time></div><blockquote className="mt-6 text-lg font-semibold leading-7">“{review.comment || 'Traveler left a rating without a written comment.'}”</blockquote><p className="mt-5 text-xs text-white/42">{travelerName(review.travelerId)} · {listingName(review.listingId)}</p></article>)}</div>}</div>;
}

function NotificationsView({ data, busy, onAction }: { data: PlatformResponse; busy: boolean; onAction: OwnerAction }) {
  const unread = data.notifications.filter((item) => !item.readAt).length;
  return <div data-owner-card className="space-y-5"><div className="flex flex-wrap items-center justify-between gap-4 bg-amber-300 p-6 text-[#14231f]"><div><strong className="text-3xl font-black">{unread} unread</strong><p className="mt-1 text-sm">Booking, review, and account updates</p></div><button disabled={busy || unread === 0} onClick={() => onAction({ action: 'mark-all-notifications-read' }, 'All notifications marked as read.')} className="min-h-11 bg-[#14231f] px-5 text-sm font-black text-white disabled:opacity-50">Mark all read</button></div>{data.notifications.length === 0 ? <section className="border border-white/10 bg-[#102622] p-8"><EmptyState icon={Bell} title="No notifications" text="Operational events will appear here as travelers and administrators interact with your account."/></section> : <div className="divide-y divide-white/10 border border-white/10 bg-[#102622]">{data.notifications.map((item) => <article key={item.id} className={`flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between ${item.readAt ? 'opacity-55' : ''}`}><div><strong>{item.title}</strong><p className="mt-1 max-w-2xl text-sm leading-6 text-white/48">{item.body}</p><time className="mt-2 block text-xs text-white/30">{new Date(item.createdAt).toLocaleString()}</time></div>{!item.readAt && <button disabled={busy} onClick={() => onAction({ action: 'mark-notification-read', id: item.id }, 'Notification marked as read.')} className="min-h-10 shrink-0 border border-white/20 px-4 text-xs font-bold">Mark read</button>}</article>)}</div>}</div>;
}

function FinanceView({ data, busy, listingName, travelerName, onRelease }: { data: PlatformResponse; busy: boolean; listingName: (id: string) => string; travelerName: (id: string) => string; onRelease: (id: string) => void }) {
  return <div data-owner-card className="space-y-5"><div className="flex gap-3 border-l-2 border-amber-300 bg-amber-300/10 p-4 text-sm leading-6 text-amber-100"><AlertTriangle size={19} className="mt-0.5 shrink-0"/><p>Payment states are a database-backed simulation. No real money moves until PayMongo is integrated and explicitly enabled.</p></div><section className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 sm:grid-cols-3"><Metric icon={WalletCards} label="Held" value={money(data.metrics.held)} helper="Simulated funds waiting"/><Metric icon={CheckCircle2} label="Released" value={money(data.metrics.released)} helper="Marked complete by owner"/><Metric icon={ShieldCheck} label="Frozen" value={money(data.metrics.frozen)} helper="Simulated protected funds"/></section>{data.bookings.length === 0 ? <section className="border border-white/10 bg-[#102622] p-8"><EmptyState icon={WalletCards} title="No payment records" text="Booking payment states will appear here when travelers reserve approved inventory."/></section> : <div className="divide-y divide-white/10 border border-white/10 bg-[#102622]">{data.bookings.map((item) => <article key={item.id} className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between"><div><strong>{listingName(item.listingId)}</strong><p className="mt-1 text-xs text-white/38">{travelerName(item.travelerId)} · {item.id}</p></div><div className="sm:text-right"><p className="font-mono text-lg font-bold">{money(item.amount)}</p><p className="mt-1 text-xs text-white/42">{titleCase(item.paymentStatus)}</p></div>{item.paymentStatus === 'PAID_HELD' && <button disabled={busy} onClick={() => onRelease(item.id)} className="min-h-11 border border-emerald-300/50 px-4 text-xs font-bold text-emerald-200 transition hover:bg-emerald-300 hover:text-[#14231f] disabled:opacity-50">Mark released</button>}</article>)}</div>}</div>;
}

function TransactionHistory({ data }: { data: PlatformResponse }) {
  return <section data-owner-card className="border border-white/10 bg-[#102622] p-5 sm:p-7"><PanelHeading icon={CircleDollarSign} title="Transaction history" description="Every simulated authorization, refund, and payout remains auditable."/>{data.transactions.length === 0 ? <p className="text-sm text-white/42">No transaction events yet.</p> : <div className="divide-y divide-white/10">{data.transactions.map((item) => <article key={item.id} className="grid gap-2 py-4 text-sm sm:grid-cols-[1fr_auto_auto] sm:items-center sm:gap-6"><span><strong className="capitalize">{item.kind}</strong><small className="mt-1 block text-white/38">{item.note}</small></span><Status value={item.status}/><span className="font-mono font-bold">{money(item.amount)}</span></article>)}</div>}</section>;
}

function ProfileView({ data, busy, onSubmit, onDocument }: { data: PlatformResponse; busy: boolean; onSubmit: (phone: FormDataEntryValue | null, bio: FormDataEntryValue | null) => void; onDocument: (body: Record<string, unknown>) => void }) {
  return <div data-owner-card className="space-y-5"><div className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 xl:grid-cols-12"><section className="bg-[#efe8d6] p-6 text-[#14231f] sm:p-9 xl:col-span-5"><ShieldCheck size={28}/><h2 className="mt-7 text-4xl font-black tracking-[-0.05em]">Trust is part of the booking decision.</h2><p className="mt-5 text-sm leading-6 text-[#52635e]">Travelers need clear contact details and enough business context to understand who operates a listing. Verification is reviewed separately from email confirmation.</p><dl className="mt-9 divide-y divide-[#14231f]/15 border-y border-[#14231f]/15"><ProfileFact label="Account" value={data.user.accountStatus}/><ProfileFact label="Verification" value={data.user.profileStatus}/><ProfileFact label="Trust score" value={`${data.user.trustScore}/100`}/><ProfileFact label="Email" value={data.user.email}/></dl></section><form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onSubmit(form.get('phone'), form.get('bio')); }} className="bg-[#102622] p-6 sm:p-9 xl:col-span-7"><PanelHeading icon={Settings} title="Business profile" description="Keep your traveler-facing owner context accurate and concise."/><div className="space-y-5"><Field label="Phone"><input name="phone" defaultValue={data.user.phone}/></Field><Field label="About your business"><textarea name="bio" defaultValue={data.user.bio} rows={7}/></Field><button disabled={busy} className="inline-flex min-h-12 items-center justify-center gap-3 bg-amber-300 px-5 py-3 text-sm font-black text-[#14231f] transition hover:bg-amber-200 disabled:opacity-50">Submit verification update <ArrowRight size={16}/></button></div></form></div><DocumentPanel data={data} busy={busy} onDocument={onDocument}/></div>;
}

function DocumentPanel({ data, busy, onDocument }: { data: PlatformResponse; busy: boolean; onDocument: (body: Record<string, unknown>) => void }) {
  const [file, setFile] = useState<{ name: string; url: string } | null>(null);
  const loadFile = (selected?: File) => { if (!selected) return; if (selected.size > 1_500_000) return; const reader = new FileReader(); reader.onload = () => setFile({ name: selected.name, url: String(reader.result) }); reader.readAsDataURL(selected); };
  return <section className="grid grid-flow-dense gap-px border border-white/10 bg-white/10 xl:grid-cols-12"><form onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); if (!file) return; onDocument({ action: 'submit-owner-document', type: form.get('type'), name: file.name, fileUrl: file.url }); setFile(null); event.currentTarget.reset(); }} className="bg-[#102622] p-6 sm:p-8 xl:col-span-5"><PanelHeading icon={FileCheck2} title="Verification documents" description="Submit a business permit, registration, or valid owner identification for administrator review."/><Field label="Document type"><select name="type"><option value="business_permit">Business permit</option><option value="registration">Business registration</option><option value="owner_id">Owner identification</option></select></Field><label className="mt-4 flex min-h-28 cursor-pointer flex-col items-center justify-center border border-dashed border-white/20 p-5 text-center hover:border-amber-300"><FileCheck2 size={22} className="text-amber-300"/><span className="mt-3 text-sm font-bold">{file?.name || 'Choose PDF or image under 1.5 MB'}</span><input className="sr-only" type="file" accept="image/*,.pdf" onChange={(event) => loadFile(event.target.files?.[0])}/></label><button disabled={busy || !file} className="mt-4 min-h-12 w-full bg-amber-300 px-5 text-sm font-black text-[#14231f] disabled:opacity-50">Submit document</button></form><div className="bg-[#14231f] p-6 sm:p-8 xl:col-span-7"><h2 className="text-3xl font-black">Submission history</h2>{data.ownerDocuments.length === 0 ? <p className="mt-5 text-sm text-white/42">No verification documents submitted.</p> : <div className="mt-6 divide-y divide-white/10">{data.ownerDocuments.map((document) => <article key={document.id} className="flex items-center justify-between gap-4 py-4"><span><strong>{document.name}</strong><small className="mt-1 block capitalize text-white/38">{document.type.replaceAll('_', ' ')} · {new Date(document.createdAt).toLocaleDateString()}</small></span><Status value={document.status}/></article>)}</div>}</div></section>;
}

function ProfileFact({ label, value }: { label: string; value: string }) { return <div className="flex items-start justify-between gap-5 py-4"><dt className="text-xs font-semibold text-[#5a6b65]">{label}</dt><dd className="max-w-[65%] break-words text-right text-sm font-black capitalize">{value}</dd></div>; }

function ListingDialog({ listing, busy, onClose, onSave }: { listing?: Listing; busy: boolean; onClose: () => void; onSave: (body: Record<string, unknown>) => Promise<void> }) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const nameRef = useRef<HTMLInputElement | null>(null);
  const [images, setImages] = useState<string[]>(listing?.imageUrls?.length ? listing.imageUrls : listing?.imageUrl ? [listing.imageUrl] : []);
  const loadImages = (files: FileList | null) => { if (!files) return; [...files].filter((file) => file.size <= 1_000_000).slice(0, Math.max(0, 8 - images.length)).forEach((file) => { const reader = new FileReader(); reader.onload = () => setImages((current) => [...new Set([...current, String(reader.result)])].slice(0, 8)); reader.readAsDataURL(file); }); };
  useModalAccessibility({ active: true, containerRef, initialFocusRef: nameRef, onClose });
  return <div ref={containerRef} className="fixed inset-0 z-50 grid place-items-center bg-[#07110f]/88 p-4 backdrop-blur-sm" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><form role="dialog" aria-modal="true" aria-label={listing ? `Edit ${listing.name}` : 'New listing'} aria-describedby="listing-dialog-description" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const imageUrl = String(form.get('imageUrl') || '').trim(); void onSave({ action: listing ? 'update-listing' : 'create-listing', id: listing?.id, name: form.get('name'), category: form.get('category'), municipality: form.get('municipality'), price: Number(form.get('price')), capacity: Number(form.get('capacity')), address: form.get('address'), description: form.get('description'), amenities: form.get('amenities'), imageUrls: [...new Set([...images, ...(imageUrl ? [imageUrl] : [])])] }); }} className="max-h-[92vh] w-full max-w-3xl overflow-y-auto border border-white/15 bg-[#102622] shadow-2xl"><div className="flex items-start justify-between border-b border-white/10 p-5 sm:p-7"><div><p className="text-xs font-semibold text-cyan-200">Traveler-facing inventory</p><h2 className="mt-1 text-3xl font-black tracking-[-0.04em]">Listing editor</h2><p id="listing-dialog-description" className="mt-2 max-w-xl text-sm leading-6 text-white/45">{listing ? `Update ${listing.name} without losing its operating history.` : 'Add accurate details for administrator review. Approved inventory becomes available to travelers.'}</p></div><button type="button" aria-label="Close listing editor" title="Close" onClick={onClose} className="grid h-10 w-10 shrink-0 place-items-center border border-white/10 transition hover:bg-white/10"><X size={18}/></button></div><div className="grid gap-4 p-5 sm:grid-cols-2 sm:p-7"><Field label="Name"><input ref={nameRef} required name="name" defaultValue={listing?.name}/></Field><Field label="Category"><select name="category" defaultValue={listing?.category || 'stay'}><option value="stay">Stay</option><option value="activity">Activity</option><option value="food">Food</option><option value="transport">Transport</option></select></Field><Field label="City / municipality"><select required name="municipality" defaultValue={listing?.municipality || 'Cordova'}>{CEBU_LOCATIONS.map((location) => <option key={location} value={location}>{location}</option>)}</select></Field><Field label="Price (PHP)"><input required min="1" type="number" name="price" defaultValue={listing?.price}/></Field><Field label="Capacity"><input required min="1" type="number" name="capacity" defaultValue={listing?.capacity}/></Field><Field label="Address" wide><input name="address" defaultValue={listing?.address}/></Field><Field label="Amenities (comma separated)" wide><input name="amenities" defaultValue={listing?.amenities.join(', ')}/></Field><Field label="Add image URL" wide><input type="url" name="imageUrl" placeholder="https://example.com/photo.jpg"/></Field><Field label="Upload gallery photos (up to 8, 1 MB each)" wide><input type="file" accept="image/*" multiple onChange={(event) => loadImages(event.target.files)}/></Field>{images.length > 0 && <div className="grid grid-cols-2 gap-2 sm:col-span-2 sm:grid-cols-4">{images.map((src, index) => <div key={`${src.slice(0, 32)}-${index}`} className="group relative aspect-[4/3] overflow-hidden bg-black/20"><Image src={src} alt={`Listing gallery ${index + 1}`} fill sizes="180px" className="object-cover"/><button type="button" aria-label={`Remove image ${index + 1}`} onClick={() => setImages((current) => current.filter((_, itemIndex) => itemIndex !== index))} className="absolute right-1 top-1 grid h-8 w-8 place-items-center bg-[#14231f] text-white"><X size={14}/></button></div>)}</div>}<Field label="Description" wide><textarea rows={4} name="description" defaultValue={listing?.description}/></Field></div><div className="flex flex-col-reverse gap-2 border-t border-white/10 p-5 sm:flex-row sm:justify-end sm:p-7"><button type="button" onClick={onClose} className="min-h-12 px-5 text-sm font-bold text-white/65">Cancel</button><button disabled={busy} className="min-h-12 bg-amber-300 px-5 text-sm font-black text-[#14231f] disabled:opacity-50">{listing ? 'Save changes' : 'Submit listing'}</button></div></form></div>;
}

function Field({ label, wide = false, children }: { label: string; wide?: boolean; children: React.ReactNode }) { return <label className={`text-xs font-semibold text-white/58 ${wide ? 'sm:col-span-2' : ''}`}>{label}<div className="mt-2 [&>*]:min-h-12 [&>*]:w-full [&>*]:border [&>*]:border-white/15 [&>*]:bg-[#071a16] [&>*]:px-4 [&>*]:py-3 [&>*]:text-sm [&>*]:text-white [&>*]:outline-none [&>*]:transition focus-within:[&>*]:border-cyan-300">{children}</div></label>; }
function Status({ value }: { value: string }) { const palette = value === 'approved' || value === 'confirmed' || value === 'completed' ? 'border-emerald-300/35 bg-emerald-300/10 text-emerald-200' : value === 'pending' || value.includes('requested') ? 'border-amber-300/35 bg-amber-300/10 text-amber-200' : 'border-red-300/35 bg-red-300/10 text-red-200'; return <span className={`inline-flex border px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.08em] ${palette}`}>{value.replaceAll('_', ' ')}</span>; }
